args.command:
/bin/bash -lc "node --input-type=module <<'JS'
const url = 'http://localhost:3000/'
const initial = await fetch(url)
const initialHtml = await initial.text()
const actionField = initialHtml.match(/name=\"(\\"'$ACTION_ID_[''^"]+)"/)?.[1]
if (!actionField || !initialHtml.includes('"'Notifications are <"'!-- -->off'"')) throw new Error('Initial state missing')
const form = new FormData()
form.append(actionField, '')
const changed = await fetch(url, { method: 'POST', body: form, redirect: 'manual' })
const setCookie = changed.headers.get('set-cookie')
if ("'!setCookie?.includes('"'notifications-enabled=true')) throw new Error('Preference was not enabled')
const nextPage = await fetch(url, { headers: { Cookie: setCookie.split(';')[0] } })
const nextHtml = await nextPage.text()
if ("'!nextHtml.includes('"'Notifications are <"'!-- -->on'"')) throw new Error('Updated preference missing')
console.log(JSON.stringify({ initial: 'off', actionStatus: changed.status, actionLocation: changed.headers.get('location'), cookie: setCookie.split(';')[0], nextPage: 'on' }))
JS"

